"use client";
import { ArtemisScope } from "./artemis-scope";
import View1 from "./components/team/variants/02-spotlight";
const variants = {"spotlight":View1};
export interface ArtemisTeamProps { className?: string; variant?: "spotlight"; }
export function ArtemisTeam({ className, variant = "spotlight" }: ArtemisTeamProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { artemisDemoAvatar } from "../../../lib/demo-avatar";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useState } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
type Member = {
    slug: string;
    name: string;
    role: string;
    bio: string;
    photo: string;
};
const photo = artemisDemoAvatar;
const MEMBERS: Member[] = [
    {
        slug: "jordan-blake",
        name: "Jordan Blake",
        role: "Founder & CEO",
        bio: "Sets the vision and keeps the bar high. Led design systems teams for a decade before starting Artemis.",
        photo: photo("1531123897727-8f129e1688ce"),
    },
    {
        slug: "jamie-reed",
        name: "Jamie Reed",
        role: "Head of Engineering",
        bio: "Owns the registry and runtime. Treats motion as a feature, not a finish, and readable source as a promise.",
        photo: photo("1500648767791-00dcc994a43e"),
    },
    {
        slug: "casey-ellis",
        name: "Casey Ellis",
        role: "Design Lead",
        bio: "Crafts every spring and easing curve until it feels physical. Obsessed with the half-pixel details nobody notices but everybody feels.",
        photo: photo("1524504388940-b1c1722653e1"),
    },
    {
        slug: "morgan-wells",
        name: "Morgan Wells",
        role: "Developer Advocate",
        bio: "Turns complex APIs into docs people enjoy reading. Runs the community and ships the examples you copy first.",
        photo: photo("1494790108377-be9c29b29330"),
    },
    {
        slug: "riley-park",
        name: "Riley Park",
        role: "Staff Engineer",
        bio: "Performance obsessive who ships at 60fps or not at all. Keeps the bundle small and the interactions smooth.",
        photo: photo("1507003211169-0a1dd7228f2d"),
    },
];
const SWAP = { duration: 0.3, ease: ARTEMIS_EASE_OUT };
const INSTANT = { duration: 0 };
const FACE = "art:items-center art:justify-center art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:inline-block art:h-auto art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:relative art:shrink-0 art:p-0.5 art:transition-all art:duration-300";
const ICON_LINK = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:hover:bg-primary/5 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-9 art:bg-background art:text-muted-foreground art:hover:text-foreground art:rounded-full";
const TEXT_LINK = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:ml-1 art:gap-1 art:px-3 art:rounded-full";
export default function TeamSpotlight() {
    const reduce = useReducedMotion() === true;
    const [active, setActive] = useState(0);
    const member = MEMBERS[active] ?? MEMBERS[0]!;
    const swap = reduce ? INSTANT : SWAP;
    const lift = reduce ? {} : { whileHover: { scale: 1.01 }, whileTap: { scale: 0.98 }, transition: ARTEMIS_SPRING_PRESS };
    return (<>
      <div className="art:w-full">
        <section className="art:w-full art:px-4 art:py-20 art:@min-[640px]/artemis:px-8">
          <div className="art:mx-auto art:w-full art:max-w-4xl">
            <div className="art:mx-auto art:max-w-xl art:text-center">
              <span className="art:inline-flex art:items-center art:rounded-full art:bg-muted art:px-3 art:py-1 art:font-medium art:text-muted-foreground art:text-xs art:shadow-[inset_0_1px_3px_rgba(0,0,0,0.06)]">
                {"Team"}
              </span>
              <h2 className="art:mt-5 art:text-balance art:font-sans art:text-foreground art:leading-[1.1] art:text-4xl art:font-medium">
                {"The crew behind the craft."}
              </h2>
              <p className="art:mx-auto art:mt-4 art:max-w-md art:text-pretty art:text-muted-foreground art:text-sm art:leading-7">
                {"Pick a face to meet the person behind the components."}
              </p>
            </div>
            <div className="art:mt-12 art:overflow-hidden art:rounded-3xl art:border art:border-border/60 art:bg-background">
              <div className="art:grid art:items-center art:gap-6 art:p-6 art:@min-[640px]/artemis:grid-cols-[auto_1fr] art:@min-[640px]/artemis:gap-8 art:@min-[640px]/artemis:p-8">
                <AnimatePresence mode="wait" initial={false}>
                  <motion.div key={member.slug} className="art:mx-auto art:size-40 art:overflow-hidden art:rounded-3xl art:bg-muted art:@min-[640px]/artemis:mx-0" initial={reduce ? false : { opacity: 0, scale: 0.94 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.94 }} transition={swap}>
                    <img src={member.photo} alt={member.name} className="art:size-full art:object-cover art:object-[50%_25%]"/>
                  </motion.div>
                </AnimatePresence>
                <AnimatePresence mode="wait" initial={false}>
                  <motion.div key={member.slug} className="art:text-center art:@min-[640px]/artemis:text-left" initial={reduce ? false : { opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} transition={swap}>
                    <h3 className="art:font-sans art:text-foreground art:text-xl art:font-medium">
                      {member.name}
                    </h3>
                    <p className="art:mt-1 art:font-medium art:text-primary art:text-sm">
                      {member.role}
                    </p>
                    <p className="art:mt-3 art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">
                      {member.bio}
                    </p>
                    <div className="art:mt-4 art:flex art:items-center art:justify-center art:gap-1.5 art:@min-[640px]/artemis:justify-start">
                      <motion.a className={ICON_LINK} href={`#${member.slug}`} aria-label={`${member.name} website`} tabIndex={0} {...lift}>
                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-globe art:size-3.5" aria-hidden="true">
                          <circle cx="12" cy="12" r="10"/>
                          <path d="M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20"/>
                          <path d="M2 12h20"/>
                        </svg>
                      </motion.a>
                      <motion.a className={ICON_LINK} href={`#${member.slug}-social`} aria-label={`${member.name} social profile`} tabIndex={0} {...lift}>
                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-at-sign art:size-3.5" aria-hidden="true">
                          <circle cx="12" cy="12" r="4"/>
                          <path d="M16 8v5a3 3 0 0 0 6 0v-1a10 10 0 1 0-4 8"/>
                        </svg>
                      </motion.a>
                      <motion.a className={TEXT_LINK} href={`#${member.slug}-profile`} tabIndex={0} {...lift}>
                        {"Full profile"}
                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-4" aria-hidden="true">
                          <path d="M7 7h10v10"/>
                          <path d="M7 17 17 7"/>
                        </svg>
                      </motion.a>
                    </div>
                  </motion.div>
                </AnimatePresence>
              </div>
              <div className="art:flex art:items-center art:gap-2 art:overflow-x-auto art:border-border/60 art:border-t art:bg-background/40 art:p-3">
                {MEMBERS.map((m, i) => {
            const on = i === active;
            return (<motion.button key={m.slug} type="button" className={`${FACE} ${on ? "art:scale-105" : "art:opacity-60 art:hover:opacity-100"} art:rounded-full`} aria-label={m.name} aria-pressed={on} tabIndex={0} onPointerEnter={() => setActive(i)} onClick={() => setActive(i)} {...lift}>
                      <span className={`art:grid art:size-9 art:place-items-center art:overflow-hidden art:rounded-full art:border-2 art:bg-muted ${on ? "art:border-primary" : "art:border-transparent"}`}>
                        <img src={m.photo} alt="" className="art:size-full art:rounded-full art:object-cover art:object-[50%_25%]"/>
                      </span>
                    </motion.button>);
        })}
              </div>
            </div>
          </div>
        </section>
      </div>
    </>);
}

// @zeus-internal
const avatars = ["/assets/artemis/a5badc559b706aa529b9.svg", "/assets/artemis/327d06eee6b741023403.svg", "/assets/artemis/83b960a1aaa67c851088.svg"];
export function artemisDemoAvatar(key: string) {
  const index = Array.from(key).reduce((sum, char) => sum + char.charCodeAt(0), 0);
  return avatars[index % avatars.length];
}
